  INSERT INTO public.cbk_preguntas (id, pregunta_origen_id, version, area_id, grado, tema, tags, competencia, enunciado, contexto, recurso_ruta, tipo_recurso, tipo, dificultad, explicacion, procedencia, fuente_nombre, fuente_url, licencia, estado, creado_por, actualizado_por, publicado_en)
  VALUES
    ('00000000-2026-5000-8000-000000000001', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'solidos']::text[], 'Clasifica materiales según su estado y propiedades observables', '¿Por qué una piedra se clasifica como un sólido?', 'Valeria observa una piedra sobre la mesa.', NULL, NULL, 'seleccion_unica', 1, 'La piedra es sólida porque tiene forma propia y conserva su forma.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000002', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos']::text[], 'Reconoce propiedades básicas de los líquidos', 'Si pasamos agua de una botella a un vaso, ¿qué ocurre con su forma?', 'El agua se vierte sin derramarse.', NULL, NULL, 'seleccion_unica', 1, 'Los líquidos no tienen forma propia; adoptan la forma del recipiente.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000003', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'gases', 'aire']::text[], 'Reconoce el aire como materia aunque no sea visible', '¿Cuál experiencia muestra que el aire está presente?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Al inflar el globo, el aire entra y ocupa espacio.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000004', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos', 'viscosidad']::text[], 'Compara propiedades observables de diferentes líquidos', '¿Cuál líquido fluye más lentamente al inclinar una cuchara?', 'Se comparan agua, aceite, miel y jugo.', NULL, NULL, 'seleccion_unica', 2, 'La miel es más viscosa y por eso fluye más lentamente que el agua o el jugo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000005', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos', 'fluidez']::text[], 'Identifica la fluidez como propiedad de los líquidos', '¿Qué tienen en común el agua y el aceite?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El agua y el aceite son líquidos y pueden fluir.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000006', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'solidos']::text[], 'Clasifica objetos cotidianos según su estado', '¿Cuál de estos elementos es un sólido?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Un cubo de hielo es agua en estado sólido y tiene forma propia.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000007', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'gases']::text[], 'Diferencia sólidos, líquidos y gases', '¿En qué estado se encuentra el vapor de agua?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El vapor de agua corresponde al estado gaseoso.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000008', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'gases', 'aire']::text[], 'Interpreta evidencias de que el aire ocupa espacio', 'Una botella vacía y tapada no se puede aplastar fácilmente. ¿Qué hay dentro de ella?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Aunque no lo veamos, dentro de la botella hay aire que ocupa espacio.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000009', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos']::text[], 'Predice el comportamiento de un líquido al cambiar de recipiente', 'Se vierte jugo de un vaso alto a un recipiente ancho. ¿Qué cambia?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El jugo sigue siendo líquido, pero adopta la forma del nuevo recipiente.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000010', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'clasificacion-materiales']::text[], 'Clasifica materiales en sólidos, líquidos y gases', '¿Cuál grupo está ordenado como sólido, líquido y gas?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El libro es sólido, la leche es líquida y el aire es gaseoso.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000011', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos', 'transparencia']::text[], 'Compara líquidos por sus propiedades observables', '¿Cuál líquido permite ver con mayor claridad un objeto colocado detrás?', 'Los recipientes contienen agua limpia, leche, chocolate y miel.', NULL, NULL, 'seleccion_unica', 2, 'El agua limpia es transparente y deja pasar más luz.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000012', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'liquidos', 'viscosidad']::text[], 'Relaciona la viscosidad con la rapidez de flujo', 'En una carrera por una tabla inclinada, ¿qué líquido probablemente llegará primero?', 'Compiten una gota de agua y una gota de miel.', NULL, NULL, 'seleccion_unica', 3, 'El agua es menos viscosa que la miel y fluye con mayor rapidez.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000013', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'solidos']::text[], 'Reconoce que los sólidos conservan su forma', '¿Qué objeto conserva su forma aunque lo cambiemos de caja?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El lápiz es sólido y conserva su forma al cambiarlo de recipiente.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000014', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'gases', 'aire']::text[], 'Describe el comportamiento de los gases', '¿Qué sucede con el aire cuando entra en un globo?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El aire se distribuye y ocupa espacio dentro del globo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000015', NULL, 1, 2, 2, 'Estados de la materia', ARRAY['estados-materia', 'aire', 'observacion']::text[], 'Propone experiencias sencillas para reconocer el aire', '¿Qué acción permite sentir el movimiento del aire?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Al abanicarnos, el aire se mueve y podemos sentirlo en la piel.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000016', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'plastilina', 'aplastar']::text[], 'Reconoce que una fuerza puede cambiar la forma de un objeto', '¿Qué ocurre al presionar una bola de plastilina con la mano?', NULL, NULL, NULL, 'seleccion_unica', 1, 'La presión de la mano aplica una fuerza que deforma la plastilina.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000017', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'estirar', 'elasticidad']::text[], 'Relaciona una acción mecánica con la deformación producida', '¿Qué acción cambia la longitud de una banda elástica?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Al estirar la banda aplicamos una fuerza que aumenta temporalmente su longitud.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000018', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'comprimir', 'esponja']::text[], 'Identifica cambios de forma causados por compresión', '¿Qué sucede al apretar una esponja suave?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Apretar aplica una fuerza de compresión que reduce temporalmente el tamaño de la esponja.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000019', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'torcer', 'tela']::text[], 'Diferencia acciones que deforman materiales', '¿Qué acción hacemos con un paño mojado para sacar parte del agua?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Al torcer el paño aplicamos fuerzas que cambian su forma y expulsan agua.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000020', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'doblar', 'papel']::text[], 'Predice el efecto de una fuerza sobre el papel', '¿Qué ocurre si doblamos una hoja de papel por la mitad?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Doblar aplica una fuerza que deforma el papel y produce un pliegue.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000021', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'resistencia-materiales', 'madera']::text[], 'Compara materiales según su resistencia a la deformación', '¿Cuál objeto es más difícil de comprimir con las manos?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La madera ofrece mayor resistencia a la compresión que la esponja, el algodón o el cojín.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000022', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'resistencia-materiales', 'plastilina']::text[], 'Compara cambios de forma en materiales distintos', 'Si presionamos con igual fuerza una cuchara metálica y plastilina, ¿cuál cambia más fácilmente de forma?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La plastilina se deforma con menor fuerza que una cuchara metálica.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000023', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'elasticidad', 'resorte']::text[], 'Reconoce materiales que recuperan su forma', '¿Qué suele hacer un resorte después de comprimirlo y soltarlo?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Un resorte es elástico y puede recuperar su forma al dejar de aplicar la fuerza.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000024', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'deformacion-permanente', 'arcilla']::text[], 'Distingue deformaciones temporales y permanentes', 'Después de moldear una figura de arcilla, ¿qué ocurre al retirar las manos?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La arcilla puede conservar la forma producida por la fuerza aplicada.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000025', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'aplastar', 'lata']::text[], 'Selecciona la acción necesaria para producir una deformación', '¿Qué acción puede aplanar una lata vacía y delgada?', 'La actividad debe realizarla un adulto con cuidado.', NULL, NULL, 'seleccion_unica', 2, 'Comprimir aplica una fuerza capaz de deformar una lata delgada.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000026', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'arrugar', 'papel']::text[], 'Relaciona fuerzas con cambios visibles en objetos', '¿Qué cambio se produce al arrugar una hoja?', NULL, NULL, NULL, 'seleccion_unica', 1, 'La fuerza de las manos cambia la forma de la hoja y crea pliegues.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000027', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'elasticidad', 'globo']::text[], 'Predice la respuesta de un material flexible a una fuerza', '¿Qué ocurre al apretar suavemente un globo inflado y luego soltarlo?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El caucho flexible cambia de forma mientras se aplica la fuerza y puede recuperarla al soltarlo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000028', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'estirar', 'seguridad']::text[], 'Reconoce límites en la deformación de materiales', '¿Qué puede pasar si estiramos demasiado una banda elástica?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Una fuerza excesiva puede superar la resistencia del material y romperlo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000029', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'resistencia-materiales', 'comparacion']::text[], 'Clasifica materiales por su resistencia a deformarse', '¿Cuál material se deforma más fácilmente al presionarlo?', 'Se comparan espuma, madera, vidrio y metal.', NULL, NULL, 'seleccion_unica', 2, 'La espuma es blanda y se comprime con mayor facilidad.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000030', NULL, 1, 2, 2, 'Fuerza y deformación', ARRAY['fuerzas-deformacion', 'empujar', 'movimiento']::text[], 'Reconoce efectos de una fuerza sobre un objeto', '¿Qué puede ocurrir al empujar una pelota que está quieta?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Un empujón es una fuerza que puede poner en movimiento la pelota.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000031', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'adaptaciones', 'desplazamiento']::text[], 'Relaciona características físicas con el ambiente donde vive un animal', '¿Cómo ayudan las patas palmeadas a un pato?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Las membranas entre los dedos impulsan el agua y facilitan la natación.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000032', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'adaptaciones', 'ambiente-acuatico']::text[], 'Explica cómo una característica ayuda a vivir en cierto ambiente', '¿Qué característica permite a los peces obtener oxígeno del agua?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Los peces usan sus branquias para obtener oxígeno disuelto en el agua.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000033', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'adaptaciones', 'proteccion']::text[], 'Relaciona cubiertas corporales con protección y ambiente', '¿Para qué sirve el pelaje grueso de un oso que vive en un lugar frío?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El pelaje grueso ayuda a proteger al animal de las bajas temperaturas.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000034', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'plantas', 'ambiente-seco']::text[], 'Relaciona estructuras de las plantas con sus necesidades', '¿Qué ventaja tiene un cactus al almacenar agua en su tallo?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El agua almacenada ayuda al cactus durante periodos con poca lluvia.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000035', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'plantas', 'raices']::text[], 'Reconoce funciones de estructuras vegetales en el ambiente', '¿Qué parte de una planta absorbe principalmente agua del suelo?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Las raíces toman agua y minerales del suelo y ayudan a sostener la planta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000036', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'adaptaciones', 'desplazamiento']::text[], 'Clasifica animales según su forma de desplazamiento', '¿Qué característica ayuda principalmente a un ave a volar?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Las alas permiten a muchas aves desplazarse por el aire.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000037', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'dieta', 'herbivoros']::text[], 'Clasifica animales según su dieta', 'Una vaca se alimenta principalmente de pasto. ¿Cómo se clasifica por su dieta?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Los animales herbívoros se alimentan principalmente de plantas.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000038', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'dieta', 'carnivoros']::text[], 'Relaciona el tipo de alimento con la dieta animal', 'Un león se alimenta de otros animales. ¿Cómo se clasifica por su dieta?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Los carnívoros se alimentan principalmente de otros animales.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000039', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'proteccion', 'caparazon']::text[], 'Identifica estructuras corporales de protección', '¿Cómo protege el caparazón a una tortuga?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El caparazón es una cubierta dura que protege el cuerpo de la tortuga.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000040', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'proteccion', 'concha']::text[], 'Explica la función protectora de una estructura animal', 'Cuando un caracol siente peligro, ¿qué estructura usa como refugio?', NULL, NULL, NULL, 'seleccion_unica', 1, 'La concha protege el cuerpo blando del caracol.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000041', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'habitats', 'anfibios']::text[], 'Relaciona necesidades de un animal con su hábitat', '¿Qué lugar es más adecuado para una rana?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Las ranas necesitan humedad y suelen vivir cerca de fuentes de agua.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000042', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'habitats', 'ambiente-seco']::text[], 'Predice qué animal está mejor adaptado a un ambiente', '¿Qué animal puede vivir mejor en un lugar muy seco y con poca agua?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El camello posee características que le permiten vivir en ambientes secos.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000043', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'necesidades-basicas', 'luz']::text[], 'Predice efectos de no satisfacer una necesidad de las plantas', '¿Qué puede ocurrir con una planta que permanece muchos días sin luz?', NULL, NULL, NULL, 'seleccion_unica', 3, 'La luz es necesaria para que las plantas produzcan su alimento y se desarrollen.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000044', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'necesidades-basicas', 'agua']::text[], 'Predice efectos de la falta de agua en una planta', '¿Qué señal puede mostrar una planta que no recibe suficiente agua?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La falta de agua puede hacer que las hojas pierdan firmeza y se marchiten.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000045', NULL, 1, 2, 2, 'Seres vivos y ambiente', ARRAY['seres-vivos-ambiente', 'necesidades-basicas', 'habitat']::text[], 'Reconoce necesidades básicas de los animales', '¿Qué conjunto reúne necesidades básicas de un animal?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Los animales necesitan agua, alimento, aire y un ambiente que les brinde protección.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000046', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'germinacion']::text[], 'Ordena cambios en el ciclo de vida de una planta', '¿Qué proceso comienza cuando una semilla recibe agua y condiciones adecuadas?', NULL, NULL, NULL, 'seleccion_unica', 1, 'La germinación es el inicio del crecimiento de una nueva planta desde la semilla.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000047', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'germinacion']::text[], 'Reconoce cambios tempranos durante la germinación', '¿Qué estructura suele aparecer primero cuando germina una semilla de fríjol?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La primera raíz ayuda a fijar la planta y a absorber agua.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000048', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'crecimiento-plantas']::text[], 'Describe cambios físicos durante el desarrollo de una planta', 'Después de germinar, ¿qué cambio muestra que una planta está creciendo?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Durante el crecimiento se desarrollan el tallo y las primeras hojas.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000049', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'floracion']::text[], 'Identifica etapas del ciclo de vida vegetal', '¿Cómo se llama la etapa en la que una planta produce flores?', NULL, NULL, NULL, 'seleccion_unica', 1, 'La floración es la etapa en que aparecen flores en la planta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000050', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'frutos']::text[], 'Relaciona flores, frutos y semillas en el desarrollo vegetal', 'En muchas plantas, ¿qué puede formarse después de la flor?', NULL, NULL, NULL, 'seleccion_unica', 2, 'En muchas plantas, después de la floración se forman frutos que contienen semillas.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000051', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'semillas']::text[], 'Reconoce la función de las semillas en el ciclo de vida', '¿Qué puede originar una semilla en condiciones adecuadas?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Una semilla puede germinar y dar origen a una nueva planta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000052', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'animales', 'mariposa']::text[], 'Ordena etapas del ciclo de vida de un animal', '¿Cuál es el orden correcto del ciclo de una mariposa?', NULL, NULL, NULL, 'seleccion_unica', 3, 'La mariposa pasa por huevo, oruga, crisálida y finalmente adulta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000053', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'animales', 'rana']::text[], 'Reconoce cambios físicos en el ciclo de vida de una rana', '¿Qué etapa aparece entre el huevo y la rana adulta?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Del huevo nace un renacuajo, que cambia hasta convertirse en rana adulta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000054', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'animales', 'aves']::text[], 'Identifica etapas de crecimiento en las aves', '¿Cuál secuencia representa el crecimiento de una gallina?', NULL, NULL, NULL, 'seleccion_unica', 2, 'La gallina nace de un huevo, crece como pollito y llega a ser adulta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000055', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'animales', 'crecimiento-animal']::text[], 'Describe cambios durante el crecimiento animal', '¿Qué cambio ocurre normalmente cuando un cachorro crece?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Durante su ciclo de vida, el cachorro crece y se convierte en perro adulto.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000056', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'animales', 'crecimiento-animal']::text[], 'Compara etapas juveniles y adultas de un animal', '¿Cuál característica suele diferenciar a un animal joven de uno adulto de la misma especie?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El crecimiento suele producir cambios de tamaño y desarrollo hasta la etapa adulta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000057', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'secuencias']::text[], 'Organiza etapas del ciclo de vida de una planta', '¿Cuál secuencia está ordenada correctamente?', NULL, NULL, NULL, 'seleccion_unica', 3, 'La planta inicia como semilla, germina, crece y llega a la etapa adulta.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000058', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'observacion']::text[], 'Selecciona una forma de registrar el crecimiento de una planta', '¿Cuál es la mejor manera de observar el crecimiento de una planta de fríjol durante dos semanas?', NULL, NULL, NULL, 'seleccion_unica', 3, 'Medir y registrar diariamente permite comparar los cambios de la planta con el tiempo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000059', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'seres-vivos', 'cambios']::text[], 'Reconoce que los seres vivos cambian con el tiempo', '¿Qué afirmación describe mejor un ciclo de vida?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Los ciclos de vida representan cambios como nacimiento, crecimiento, reproducción y muerte.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-5000-8000-000000000060', NULL, 1, 2, 2, 'Ciclos de vida', ARRAY['ciclos-de-vida', 'plantas', 'reproduccion']::text[], 'Explica cómo puede reiniciarse el ciclo de una planta', '¿Cómo puede comenzar de nuevo el ciclo de vida de una planta con flores?', NULL, NULL, NULL, 'seleccion_unica', 3, 'Las semillas producidas por la planta pueden germinar y originar nuevas plantas.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL)
